def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: a :class:`datetime.timedelta` instance
    :type value: timedelta
    :return: the total number of seconds as an int if the value is an integer,
             otherwise as a float; returns None if the input is not a timedelta
             or cannot be processed.
    """
    if value is None:
        return None
    try:
        total = value.total_seconds()
    except AttributeError:
        # value does not have total_seconds method, not a timedelta
        return None
    except Exception:
        # any other error during conversion
        return None

    # Return an int if the total seconds is an integer value
    if isinstance(total, float) and total.is_integer():
        return int(total)
    return total

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: A string representation of the time, or None if value is None.
    """
    # Return None for a missing value
    if value is None:
        return None

    # If the value is a datetime.datetime, extract the time part
    if hasattr(value, "time") and callable(value.time):
        try:
            value = value.time()
        except Exception:
            # If extraction fails, fall back to the original value
            pass

    # If the value has an isoformat method, use it
    if hasattr(value, "isoformat") and callable(value.isoformat):
        try:
            return value.isoformat()
        except Exception:
            # If isoformat fails, fall back to manual formatting
            pass

    # Manual formatting for objects that expose hour, minute, second, microsecond
    try:
        hour = getattr(value, "hour")
        minute = getattr(value, "minute")
        second = getattr(value, "second", 0)
        microsecond = getattr(value, "microsecond", 0)

        if microsecond:
            return f"{hour:02d}:{minute:02d}:{second:02d}.{microsecond:06d}"
        else:
            return f"{hour:02d}:{minute:02d}:{second:02d}"
    except Exception as exc:
        raise TypeError(
            f"Cannot dehydrate value of type {type(value).__name__}"
        ) from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    try:
        lat = value.lat
        lon = value.lon
        time = value.time
    except AttributeError:
        raise TypeError("Expected a Point instance with attributes 'lat', 'lon', and 'time'")
    # Convert time to ISO format string if possible
    if hasattr(time, "isoformat"):
        time_str = time.isoformat()
    else:
        time_str = str(time)
    return {"lat": lat, "lon": lon, "time": time_str}

def keys(self):
    """Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer internal _keys dict if available
        if hasattr(self, "_keys") and isinstance(self._keys, dict):
            return list(self._keys.keys())
        # Fallback to a 'data' attribute
        if hasattr(self, "data") and isinstance(self.data, dict):
            return list(self.data.keys())
        # As a last resort, use the instance's __dict__ excluding private attributes
        return [k for k in self.__dict__ if not k.startswith("_")]
    except Exception as exc:
        raise RuntimeError(f"Unable to retrieve keys: {exc}") from exc

def unit_of_work(metadata=None, timeout=None):
    """This function is a decorator for transaction functions that allows extra control over how the transaction is carried out.

    For example, a timeout may be applied::

        from neo4j import unit_of_work

        @unit_of_work(timeout=100)
        def count_people_tx(tx):
            result = tx.run("MATCH (a:Person) RETURN count(a) AS persons")
            record = result.single()
            return record["persons"]

    :param metadata:
        a dictionary with metadata.
        Specified metadata will be attached to the executing transaction and visible in the output of ``dbms.listQueries`` and ``dbms.listTransactions`` procedures.
        It will also get logged to the ``query.log``.
        This functionality makes it easier to tag transactions and is equivalent to ``dbms.setTXMetaData`` procedure, see https://neo4j.com/docs/operations-manual/current/reference/procedures/ for procedure reference.
    :type metadata: dict

    :param timeout:
        the transaction timeout in seconds.
        Transactions that execute longer than the configured timeout will be terminated by the database.
        This functionality allows to limit query/transaction execution time.
        Specified timeout overrides the default timeout configured in the database using ``dbms.transaction.timeout`` setting.
        Value should not represent a negative duration.
        A zero duration will make the transaction execute indefinitely.
        None will use the default timeout configured in the database.
    :type timeout: float or :const:`None`
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Validate metadata
            if metadata is not None and not isinstance(metadata, dict):
                raise TypeError("metadata must be a dict")
            # Validate timeout
            if timeout is not None:
                if not isinstance(timeout, (int, float)):
                    raise TypeError("timeout must be a number or None")
                if timeout < 0:
                    raise ValueError("timeout must not be negative")
            # Acquire driver
            driver = globals().get('driver')
            if driver is None:
                raise RuntimeError("Neo4j driver not available")
            with driver.session() as session:
                tx = session.begin_transaction()
                try:
                    if metadata:
                        try:
                            tx.set_metadata(metadata)
                        except Exception:
                            pass
                    if timeout is not None:
                        try:
                            tx.set_timeout(timeout)
                        except Exception:
                            pass
                    result = func(tx, *args, **kwargs)
                    tx.commit()
                    return result
                except Exception:
                    try:
                        tx.rollback()
                    except Exception:
                        pass
                    raise
        return wrapper
    return decorator

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError('Key not found: %s' % key)

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Ensure the object has a values() method
    if not hasattr(self, "values"):
        raise AttributeError("Object does not support values() method")

    all_values = list(self.values())

    # If no keys are provided, return all values
    if not keys:
        return all_values

    result = []
    for key in keys:
        # Handle integer indices
        if isinstance(key, int):
            try:
                result.append(all_values[key])
            except IndexError:
                # Skip invalid indices
                continue
        else:
            # Handle key lookups
            try:
                result.append(self[key])
            except (KeyError, TypeError):
                # Skip keys that are not present or not hashable
                continue

    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Helper to get field name and value by index
    def _get_by_index(idx):
        if idx < 0 or idx >= len(self._values):
            raise IndexError(f"Index {idx} out of bounds")
        # Determine field name from self._keys
        if isinstance(self._keys, dict):
            # Preserve order of keys as they were inserted
            key_list = list(self._keys.keys())
            field = key_list[idx]
        else:
            field = self._keys[idx]
        return field, self._values[idx]

    # If no keys specified, return all fields
    if not keys:
        if isinstance(self._keys, dict):
            return {k: self._values[i] for i, k in enumerate(self._keys)}
        return dict(zip(self._keys, self._values))

    result = {}
    for key in keys:
        if isinstance(key, int):
            field, value = _get_by_index(key)
            result[field] = value
        elif isinstance(key, str):
            if isinstance(self._keys, dict):
                if key in self._keys:
                    idx = self._keys[key]
                    result[key] = self._values[idx]
                else:
                    result[key] = None
            else:
                if key in self._keys:
                    idx = self._keys.index(key)
                    result[key] = self._values[idx]
                else:
                    result[key] = None
        else:
            raise TypeError("Keys must be integers or strings")
    return result

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # Validate mode
        if mode is None:
            mode = "WRITE"
        else:
            if mode not in ("READ", "WRITE"):
                raise ValueError("mode must be 'READ' or 'WRITE'")
        # Validate bookmarks
        if bookmarks is None:
            bookmarks = []
        else:
            try:
                bookmarks = list(bookmarks)
            except Exception:
                raise TypeError("bookmarks must be an iterable")
        # Validate metadata
        if metadata is None:
            metadata = {}
        else:
            if not isinstance(metadata, dict):
                raise TypeError("metadata must be a dict")
        # Validate timeout
        if timeout is not None and not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a number")
        # Validate db
        if db is not None and not isinstance(db, str):
            raise TypeError("db must be a string")
        # Validate imp_user
        if imp_user is not None and not isinstance(imp_user, str):
            raise TypeError("imp_user must be a string")
        # Validate dehydration_hooks
        if dehydration_hooks is None:
            dehydration_hooks = {}
        else:
            if not isinstance(dehydration_hooks, dict):
                raise TypeError("dehydration_hooks must be a dict")
        # Validate hydration_hooks
        if hydration_hooks is None:
            hydration_hooks = {}
        else:
            if not isinstance(hydration_hooks, dict):
                raise TypeError("hydration_hooks must be a dict")
        # Validate handlers
        for name, fn in handlers.items():
            if not callable(fn):
                raise TypeError(f"handler {name} must be callable")
        # Build message arguments
        args = {
            "mode": mode,
            "bookmarks": bookmarks,
            "metadata": metadata,
            "timeout": timeout,
            "db": db,
            "imp_user": imp_user,
            "dehydration_hooks": dehydration_hooks,
            "hydration_hooks": hydration_hooks,
        }
        # Remove None values
        args = {k: v for k, v in args.items() if v is not None}
        # Append to output queue
        # The exact format of the message may vary; here we use a tuple
        self._output_queue.append(("BEGIN", args))
        # Create and return a Response object
        return Response(self, handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate the class name
    if not isinstance(name, str):
        raise TypeError(f"Class name must be a string, got {type(name).__name__}")
    if not name.isidentifier():
        raise TypeError(f"Invalid class name: {name!r}")

    # Validate and normalise fields
    if fields is None:
        fields = []
    else:
        if isinstance(fields, str):
            raise TypeError("Fields cannot be a string; provide an iterable of field names")
        try:
            iter(fields)
        except TypeError:
            raise TypeError(f"Fields must be an iterable, got {type(fields).__name__}")
        # Ensure each field is a valid identifier and unique
        seen = set()
        field_list = []
        for f in fields:
            if not isinstance(f, str):
                raise TypeError(f"Field names must be strings, got {type(f).__name__}")
            if not f.isidentifier():
                raise TypeError(f"Invalid field name: {f!r}")
            if f in seen:
                raise TypeError(f"Duplicate field name: {f!r}")
            seen.add(f)
            field_list.append(f)

    # Validate srid_map
    if srid_map is None:
        srid_map = {}
    else:
        if not isinstance(srid_map, dict):
            raise TypeError(f"srid_map must be a dict, got {type(srid_map).__name__}")

    # Prepare the namespace for the new class
    namespace = {
        "__slots__": tuple(field_list),
        "SRID_MAP": srid_map,
        "__annotations__": {},  # allow type hints if desired
    }

    # Attempt to create the subclass of Point
    try:
        # Assume Point is defined in the surrounding scope
        cls = type(name, (Point,), namespace)
    except NameError as e:
        raise NameError("Point class is not defined in the current scope") from e
    except Exception as e:
        raise RuntimeError(f"Failed to create Point subclass {name!r}") from e

    return cls

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        if func.__doc__:
            wrapper.__doc__ = f"{func.__doc__}\n\n{message}"
        else:
            wrapper.__doc__ = message
        return wrapper
    return decorator

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    # Validate input
    if not isinstance(cmd, tuple):
        raise TypeError('cmd must be a tuple')
    if not all(isinstance(arg, str) for arg in cmd):
        raise TypeError('all elements of cmd must be str')
    if not cmd:
        return cmd

    # On Windows, handle shebang lines in scripts
    if os.name == 'nt':
        script = cmd[0]
        script_path = os.path.abspath(script)
        if os.path.isfile(script_path):
            try:
                with open(script_path, 'rb') as f:
                    first_line = f.readline().decode('utf-8', errors='ignore')
                if first_line.startswith('#!'):
                    shebang = first_line[2:].strip()
                    parts = shlex.split(shebang)
                    if parts:
                        interpreter = parts[0]
                        # Resolve relative interpreter paths
                        if not os.path.isabs(interpreter):
                            for dir_ in os.environ.get('PATH', '').split(os.pathsep):
                                candidate = os.path.join(dir_, interpreter)
                                if os.path.isfile(candidate):
                                    interpreter = candidate
                                    break
                        new_cmd = tuple([interpreter] + parts[1:] + list(cmd[1:]))
                        cmd = new_cmd
            except Exception:
                pass

    # Quote arguments that contain spaces or tabs
    def quote(arg: str) -> str:
        if ' ' in arg or '\t' in arg:
            return f'"{arg}"'
        return arg

    return tuple(quote(arg) for arg in cmd)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                try:
                    k = key(*args, **kwargs)
                except Exception:
                    # If key function fails, fall back to using args tuple
                    k = args
                try:
                    return cache[k]
                except KeyError:
                    pass
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except Exception:
                    # Ignore errors when setting the cache
                    pass
                return v
        else:
            def wrapper(*args, **kwargs):
                try:
                    k = key(*args, **kwargs)
                except Exception:
                    k = args
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except Exception:
                    pass
                return v
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    # Support both @mru_cache and @mru_cache(...)
    if callable(maxsize) and not isinstance(maxsize, int):
        func = maxsize
        maxsize = 128
        typed = False
        return _mru_decorator(func, maxsize, typed)

    def _mru_decorator(func, maxsize, typed):
        if not isinstance(maxsize, int) or maxsize <= 0:
            raise ValueError("maxsize must be a positive integer")
        if not isinstance(typed, bool):
            raise ValueError("typed must be a boolean")
        if not inspect.isfunction(func):
            raise ValueError("mru_cache can only be applied to functions")

        cache = collections.OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Build cache key
            if typed:
                key = (
                    args,
                    tuple(sorted(kwargs.items())),
                    tuple(type(a) for a in args),
                    tuple(type(v) for v in kwargs.values()),
                )
            else:
                key = (args, tuple(sorted(kwargs.items())))

            if key in cache:
                # Mark as most recently used
                cache.move_to_end(key)
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result

            # Evict most recently used if cache exceeds maxsize
            if len(cache) > maxsize:
                cache.popitem(last=True)

            return result

        return wrapper

    return _mru_decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        order = []
        @wraps(func)
        def wrapper(*args, **kwargs):
            if maxsize <= 0:
                return func(*args, **kwargs)
            kw_items = tuple(sorted(kwargs.items())) if kwargs else ()
            if typed:
                key = (args, kw_items,
                       tuple(type(arg) for arg in args),
                       tuple(type(value) for _, value in kw_items))
            else:
                key = (args, kw_items)
            if key in cache:
                # Move key to end to mark as recently used
                order.remove(key)
                order.append(key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            order.append(key)
            if len(order) > maxsize:
                oldest = order.pop(0)
                del cache[oldest]
            return result
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        if maxsize is None or maxsize <= 0:
            return func
        cache = {}
        freq = {}
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                key = args
                if kwargs:
                    key += tuple(sorted(kwargs.items()))
                if typed:
                    key += tuple(type(arg) for arg in args)
                    key += tuple(type(v) for v in kwargs.values())
            except TypeError:
                return func(*args, **kwargs)
            if key in cache:
                freq[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                min_key = min(freq, key=lambda k: freq[k])
                del cache[min_key]
                del freq[min_key]
            cache[key] = result
            freq[key] = 1
            return result
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError('dict is empty')
    value = dict.pop(self, key)
    return (key, value)

def setdefault(self, key, default=None):
    """ D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D """
    # Ensure the key is hashable
    try:
        hash(key)
    except TypeError:
        raise TypeError("setdefault: key must be hashable") from None

    # Attempt to use the primary dictionary attribute
    try:
        return self._value.setdefault(key, default)
    except AttributeError:
        # Fallback to an alternative storage attribute if present
        if hasattr(self, 'storage'):
            return self.storage.setdefault(key, default)
        else:
            raise AttributeError("No dictionary attribute found for setdefault") from None

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except (KeyError, TypeError):
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except Exception:
                    pass
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except Exception:
                    pass
                return v
        wrapper.__name__ = method.__name__
        wrapper.__doc__ = method.__doc__
        wrapper.__dict__.update(method.__dict__)
        return wrapper
    return decorator

@staticmethod
def file_to_textbuffer(file_name, encoding):
    """Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str
    """
    try:
        with open(file_name, encoding=encoding) as f:
            return f.read()
    except Exception:
        return None

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        return os.path.isfile(file_name)
    except Exception:
        return False

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        from zope.interface import directlyProvidedBy as _zope_directlyProvidedBy
        return _zope_directlyProvidedBy(object)
    except Exception:
        # Fallback: return an empty Declaration if the object provides no interfaces
        try:
            from zope.interface.declarations import Declaration
            return Declaration()
        except Exception:
            # As a last resort, return an empty tuple
            return ()

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("all must be a bool")
    try:
        attrs = set()
        classes = self.__class__.mro() if all else [self.__class__]
        for cls in classes:
            if cls is object:
                continue
            for key, value in cls.__dict__.items():
                if callable(value):
                    continue
                if key.startswith('__') and key.endswith('__'):
                    continue
                attrs.add(key)
            slots = getattr(cls, '__slots__', None)
            if slots:
                if isinstance(slots, str):
                    slots = (slots,)
                for slot in slots:
                    if slot.startswith('__') and slot.endswith('__'):
                        continue
                    attrs.add(slot)
        return sorted(attrs)
    except Exception as exc:
        raise RuntimeError(f"Error retrieving interface names: {exc}") from exc

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If sequence is None, nothing to do
    if sequence is None:
        return output

    # Handle special case where sequence is a broken interface
    try:
        if Broken in getattr(sequence, "__bases__", ()):
            return [sequence]
    except Exception:
        # If getattr fails, ignore and continue
        pass

    cls = sequence.__class__
    # Check if sequence is an interface or implements spec
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        # Try to iterate over sequence; if not iterable, treat as single
        try:
            for v in sequence:
                _normalizeargs(v, output)
        except TypeError:
            output.append(sequence)

    return output

def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    try:
        import importlib
        return importlib.import_module('ase.optimize.c_optimizations')
    except Exception:
        return False

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    return False

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary
    self.context = {}
    # Reinitialize the bins
    try:
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Preserve the existing number of bins if possible
            bin_count = len(self.bins) if hasattr(self, "bins") else 0
            self.bins = [self.initial_value] * bin_count
        else:
            # Use the factory method to create new bins
            self.bins = self.make_bins()
    except Exception as exc:
        raise RuntimeError(f"Failed to reinitialize bins: {exc}") from exc

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Retrieve the error array for the given coordinate name
    try:
        err = self.errors[coord_name]
    except (AttributeError, KeyError):
        raise KeyError(f"Coordinate '{coord_name}' not found in error mapping.")

    # If no error data is provided, return an empty list
    if err is None:
        return []

    # Convert to a NumPy array for uniform processing
    try:
        arr = np.asarray(err)
    except Exception as exc:
        raise TypeError(f"Error data for coordinate '{coord_name}' is not array-like.") from exc

    # If the array is empty, return an empty list
    if arr.size == 0:
        return []

    # Determine indices of valid error entries
    # For boolean or object arrays, use truthiness; otherwise, treat NaNs as missing
    if arr.dtype.kind in ('b', 'O'):
        try:
            indices = np.where(arr)[0]
        except Exception:
            # Fallback: treat non-NaN numeric values as valid
            indices = np.where(~np.isnan(arr.astype(float)))[0]
    else:
        indices = np.where(~np.isnan(arr))[0]

    return indices.tolist()

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    # Validate context
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")
    # Ensure error subcontext exists
    error_ctx = context.setdefault('error', {})
    if not isinstance(error_ctx, dict):
        raise TypeError("context['error'] must be a dict")
    # Get graph fields
    fields = getattr(self, '_fields', None)
    if fields is None:
        # Try to infer from a pandas DataFrame if present
        try:
            fields = list(getattr(self, '_data', pd.DataFrame()).columns)
        except Exception:
            # No fields available; nothing to update
            return
    if not isinstance(fields, (list, tuple)):
        # Unsupported fields type
        return
    # Build coordinate mapping: first three fields -> x, y, z
    coord_map = {}
    if hasattr(self, '_x'):
        coord_map[getattr(self, '_x')] = 'x'
        if hasattr(self, '_y'):
            coord_map[getattr(self, '_y')] = 'y'
        if hasattr(self, '_z'):
            coord_map[getattr(self, '_z')] = 'z'
    else:
        # Fallback: use first three field names
        if len(fields) >= 1:
            coord_map[fields[0]] = 'x'
        if len(fields) >= 2:
            coord_map[fields[1]] = 'y'
        if len(fields) >= 3:
            coord_map[fields[2]] = 'z'
    # Iterate over fields to find error columns
    for idx, field in enumerate(fields):
        if not isinstance(field, str):
            continue
        if not field.startswith('error_'):
            continue
        rest = field[6:]  # strip 'error_'
        # Split into coordinate part and suffix
        parts = rest.split('_', 1)
        coord_name = parts[0]
        suffix = parts[1] if len(parts) > 1 else ''
        # Map coordinate name to letter
        letter = coord_map.get(coord_name)
        if letter is None:
            # Try to infer by position in fields
            try:
                coord_idx = fields.index(coord_name)
                if coord_idx == 0:
                    letter = 'x'
                elif coord_idx == 1:
                    letter = 'y'
                elif coord_idx == 2:
                    letter = 'z'
            except ValueError:
                # Coordinate not found; skip this error field
                continue
        if letter is None:
            continue
        error_name = f"{letter}_{suffix}" if suffix else letter
        # Append index to error context
        error_ctx[error_name] = {'index': idx}
    # No return value needed; context is modified in place.

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    # Convert bins to numpy array
    bins = np.asarray(bins, dtype=float)

    # Handle 1D histogram
    if bins.ndim == 1:
        edges = np.asarray(edges, dtype=float)
        if edges.ndim != 1:
            raise ValueError("For 1D histogram, edges must be a 1D array.")
        if len(edges) != len(bins) + 1:
            raise ValueError("Length of edges must be len(bins)+1 for 1D histogram.")
        widths = np.diff(edges)
        return float(np.sum(bins * widths))

    # Handle ND histogram
    if isinstance(edges, (list, tuple)):
        if len(edges) != bins.ndim:
            raise ValueError("Number of edge arrays must match histogram dimensions.")
        widths = [np.diff(np.asarray(e, dtype=float)) for e in edges]
        # Validate each width length
        for w, dim in zip(widths, bins.shape):
            if len(w) != dim:
                raise ValueError("Each edge array must have length equal to the corresponding bin dimension + 1.")
    else:
        # Single array for all dimensions (unlikely but handle)
        edges = np.asarray(edges, dtype=float)
        if edges.ndim != 1:
            raise ValueError("Edges must be a list/tuple of arrays for ND histogram.")
        widths = [np.diff(edges)] * bins.ndim

    # Compute area grid by broadcasting widths
    area = np.ones_like(bins, dtype=float)
    for i, w in enumerate(widths):
        shape = [1] * bins.ndim
        shape[i] = -1
        area *= w.reshape(shape)

    return float(np.sum(bins * area))

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # If seq is a Source sequence, it's not a FillRequestSeq
        if isinstance(seq, Source):
            return False
        # Direct instance of FillRequest
        if isinstance(seq, FillRequest):
            return True
        # If seq is iterable, check for any FillRequest element
        for item in seq:
            if isinstance(item, FillRequest):
                return True
        return False
    except Exception:
        # Any error (e.g., non-iterable) means it cannot be a FillRequestSeq
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        run_attr = getattr(obj, 'run', None)
        return callable(run_attr)
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return (hasattr(obj, 'fill') and callable(getattr(obj, 'fill')) and
                hasattr(obj, 'compute') and callable(getattr(obj, 'compute')))
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Basic type checks
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError('d1 and d2 must be dictionaries')
    if not isinstance(level, int):
        raise TypeError('level must be an integer')
    if level < -1:
        level = -1

    def _diff(a, b, lvl):
        result = {}
        for key, val in a.items():
            if key not in b:
                # Key only in d1
                result[key] = val
            else:
                val2 = b[key]
                # Both values are dictionaries
                if isinstance(val, dict) and isinstance(val2, dict):
                    if lvl == 0:
                        # No recursion: treat dicts as values
                        if val != val2:
                            result[key] = val
                    else:
                        # Recurse into nested dictionaries
                        sublvl = lvl - 1 if lvl > 0 else -1
                        subdiff = _diff(val, val2, sublvl)
                        if subdiff:
                            result[key] = subdiff
                else:
                    # At least one value is not a dict
                    if val != val2:
                        result[key] = val
        return result

    return _diff(d1, d2, level)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    if not np.isscalar(weight):
        raise TypeError("weight must be a scalar")
    # Convert coord to array
    try:
        coord_arr = np.asarray(coord)
    except Exception as e:
        raise TypeError("coord must be array-like") from e
    # Ensure 1-D
    if coord_arr.ndim != 1:
        raise ValueError("coord must be a 1-D array of length equal to histogram dimensions")
    # Ensure required attributes exist
    if not hasattr(self, 'edges'):
        raise AttributeError("Histogram object missing 'edges' attribute")
    if not hasattr(self, 'bins'):
        raise AttributeError("Histogram object missing 'bins' attribute")
    # Ensure dimension matches
    if len(coord_arr) != len(self.edges):
        raise ValueError(f"coord length {len(coord_arr)} does not match histogram dimensions {len(self.edges)}")
    # Compute bin indices
    indices = []
    for dim, (edge, val) in enumerate(zip(self.edges, coord_arr)):
        idx = np.searchsorted(edge, val, side='right') - 1
        if idx < 0 or idx >= len(edge) - 1:
            # Outside edges, ignore
            return
        indices.append(idx)
    # Increment bin
    try:
        self.bins[tuple(indices)] += weight
    except Exception as e:
        raise RuntimeError(f"Failed to increment bin at indices {indices}") from e

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Process each element of the list
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            # Non-dict and non-list values
            if first_level:
                # Preserve scalar identifying fields at the top level
                result[key] = value
            else:
                result[key] = None
    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Ensure the inputs are of expected types
    if not isinstance(last_applied_manifest, dict):
        raise TypeError(
            "last_applied_manifest must be a dict (or dict-like) instance"
        )
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, dict):
        # If the response is not a dict, we cannot proceed
        return

    for field in observer_schema:
        # Handle simple field names
        if isinstance(field, str):
            if field not in last_applied_manifest and field in response:
                last_applied_manifest[field] = response[field]
            continue

        # Handle nested schema definitions
        if isinstance(field, dict):
            for key, sub_schema in field.items():
                # Initialize nested container if missing
                if key not in last_applied_manifest:
                    if isinstance(sub_schema, dict):
                        last_applied_manifest[key] = {}
                    elif isinstance(sub_schema, list):
                        last_applied_manifest[key] = []
                    else:
                        # Unsupported schema type; skip
                        continue

                # Retrieve the corresponding part of the response
                sub_response = response.get(key, {})
                if not isinstance(sub_response, (dict, list)):
                    # If the response part is not a container, skip recursion
                    continue

                # Recursively update nested structures
                try:
                    if isinstance(sub_schema, dict):
                        update_last_applied_manifest_dict_from_resp(
                            last_applied_manifest[key], sub_schema, sub_response
                        )
                    elif isinstance(sub_schema, list):
                        update_last_applied_manifest_list_from_resp(
                            last_applied_manifest[key], sub_schema, sub_response
                        )
                except Exception:
                    # If any error occurs during recursion, ignore and continue
                    continue
            continue

        # If the field is neither a string nor a dict, ignore it
        continue

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dict")
    if not isinstance(response, dict):
        raise TypeError("response must be a dict")
    if not isinstance(last_applied_manifest, dict):
        raise TypeError("last_applied_manifest must be a dict")

    for key, sub_schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field {key!r} not present in response")
        if isinstance(sub_schema, dict):
            # Nested dictionary: recurse
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], dict):
                last_applied_manifest[key] = {}
            if not isinstance(response[key], dict):
                raise KeyError(f"Expected dict for field {key!r} in response")
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], sub_schema, response[key]
            )
        else:
            # Leaf field: set only if not already present
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response[key]

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        if not os.path.isdir(path):
            return False
        # Check for OCFL root marker
        ocfl_marker = os.path.join(path, ".ocfl-version")
        if os.path.isfile(ocfl_marker):
            return True
        # Fallback: check for a pyfs root marker (if any)
        pyfs_marker = os.path.join(path, ".pyfs")
        if os.path.isdir(pyfs_marker):
            return True
        return False
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    status = getattr(self, 'status', None)
    if status is None:
        status_text = ''
    else:
        # If status is an enum or has a name attribute, use it; otherwise use its string representation
        status_text = status.name if hasattr(status, 'name') else str(status)
    return f"{prefix}{status_text}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    # Attempt to retrieve a log attribute; fall back to empty list if not present
    log = getattr(self, 'log', None)
    if log is None:
        log = getattr(self, 'validation_log', [])
    # Normalize log to an iterable of entries
    if isinstance(log, dict):
        log = list(log.items())
    elif not isinstance(log, (list, tuple)):
        # If log is a single object, wrap it in a list
        log = [log]
    lines = []
    for entry in log:
        try:
            line = str(entry)
        except Exception:
            line = repr(entry)
        lines.append(f"{prefix}{line}")
    return "\n".join(lines)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine the specification version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get('type')
        if isinstance(type_val, str):
            # Attempt to extract a trailing numeric version from the type string
            try:
                # e.g., "inventory_v2" or "type2"
                import re
                match = re.search(r'(\d+)$', type_val)
                if match:
                    spec_version = int(match.group(1))
            except Exception:
                # If anything goes wrong, fall back to the default spec_version
                pass

    # Required fields that every inventory should contain
    required_fields = ['name', 'type', 'items']
    for field in required_fields:
        if field not in inventory:
            raise ValueError(f"Missing required field '{field}' in inventory")

    # Validate the 'type' field
    if not isinstance(inventory['type'], str):
        raise TypeError("Inventory 'type' must be a string")

    # Validate the optional 'spec_version' field if present
    if 'spec_version' in inventory:
        inv_version = inventory['spec_version']
        if not isinstance(inv_version, int):
            raise TypeError("Inventory 'spec_version' must be an integer")
        if inv_version != spec_version:
            raise ValueError(
                f"Inventory spec_version {inv_version} does not match expected {spec_version}"
            )

    # Validate the 'items' list
    items = inventory['items']
    if not isinstance(items, list):
        raise TypeError("Inventory 'items' must be a list")
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            raise TypeError(f"Item at index {idx} must be a dict")

    # If all checks pass, return the inventory unchanged
    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure inputs are iterable
    if not manifest_files:
        return
    if digests_used is None:
        digests_used = set()
    else:
        digests_used = set(digests_used)

    missing = []
    for entry in manifest_files:
        # Extract digest from dict or object
        if isinstance(entry, dict):
            digest = entry.get('digest')
        else:
            digest = getattr(entry, 'digest', None)

        if digest is None:
            continue  # skip entries without a digest

        if digest not in digests_used:
            missing.append(digest)

    if missing:
        raise ValueError(
            f"Digests missing from used set: {', '.join(map(str, missing))}"
        )

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory cannot be None")
    if version is None:
        raise ValueError("version cannot be None")

    result = {}
    try:
        # Handle inventory as a dict mapping logical_path -> list of entries
        if isinstance(inventory, dict):
            for logical_path, entries in inventory.items():
                if not isinstance(entries, (list, tuple)):
                    continue
                for entry in entries:
                    if isinstance(entry, dict):
                        entry_version = entry.get("version")
                        content_file = entry.get("content_file")
                    else:
                        # Assume tuple (content_file, version) or (content_file, version, ...)
                        if len(entry) >= 2:
                            content_file, entry_version = entry[0], entry[1]
                        else:
                            continue
                    if entry_version == version and content_file:
                        result.setdefault(logical_path, set()).add(content_file)
        else:
            # Assume inventory is an iterable of entries
            for entry in inventory:
                if isinstance(entry, dict):
                    logical_path = entry.get("logical_path")
                    entry_version = entry.get("version")
                    content_file = entry.get("content_file")
                else:
                    # Assume tuple (logical_path, content_file, version)
                    if len(entry) >= 3:
                        logical_path, content_file, entry_version = entry[0], entry[1], entry[2]
                    else:
                        continue
                if logical_path and entry_version == version and content_file:
                    result.setdefault(logical_path, set()).add(content_file)
    except Exception as exc:
        raise RuntimeError(f"Error processing inventory: {exc}") from exc

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure manifest_files is a set or list of strings
    if not isinstance(manifest_files, (set, list, tuple)):
        raise ValueError("manifest_files must be a set, list, or tuple of file paths")
    manifest_set = set(manifest_files)

    # The fixity block must be a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # The block must contain a 'files' key
    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key")

    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' entry must be a list")

    seen_paths = set()
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"Entry {idx} in 'files' must be a dictionary")

        # Required keys for each file entry
        for key in ('path', 'hash', 'size'):
            if key not in entry:
                raise ValueError(f"Entry {idx} missing required key '{key}'")

        path = entry['path']
        if not isinstance(path, str):
            raise ValueError(f"Entry {idx} 'path' must be a string")
        if path not in manifest_set:
            raise ValueError(f"File '{path}' referenced in fixity block not found in manifest")
        if path in seen_paths:
            raise ValueError(f"Duplicate file reference '{path}' in fixity block")
        seen_paths.add(path)

        # Basic type checks for hash and size
        if not isinstance(entry['hash'], str):
            raise ValueError(f"Entry {idx} 'hash' must be a string")
        if not isinstance(entry['size'], int):
            raise ValueError(f"Entry {idx} 'size' must be an integer")

    # Optionally, ensure that every file in the manifest is referenced
    # (uncomment if desired)
    # missing_in_fixity = manifest_set - seen_paths
    # if missing_in_fixity:
    #     raise ValueError(f"Files missing from fixity block: {', '.join(missing_in_fixity)}")

def files_list(path):
    """
    Return the files in `path`
    """
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        try:
            return [os.path.abspath(os.path.join(path, f))
                    for f in os.listdir(path)
                    if os.path.isfile(os.path.join(path, f))]
        except OSError as e:
            raise e
    raise ValueError(f"Path is neither file nor directory: {path}")

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    groups = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First pass: identify XML basenames
            xml_basenames = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                base = os.path.basename(info.filename)
                name, ext = os.path.splitext(base)
                if ext.lower() == '.xml':
                    xml_basenames.add(name)

            # Second pass: collect files belonging to those basenames
            for info in zf.infolist():
                if info.is_dir():
                    continue
                base = os.path.basename(info.filename)
                name, _ = os.path.splitext(base)
                if name in xml_basenames:
                    if name not in groups:
                        groups[name] = {}
                    try:
                        content = zf.read(info)
                    except Exception as e:
                        # Skip files that cannot be read
                        continue
                    groups[name][info.filename] = content
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"Error processing zip file {zip_path}: {e}") from e

    return groups

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0]
        except Exception:
            continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate and normalize parameters
    try:
        indent = int(indent)
        if indent < 0:
            indent = 0
    except Exception:
        indent = 0
    debug = bool(debug)

    try:
        import pprint
        formatted = pprint.pformat(
            self,
            indent=indent,
            width=80,
            depth=None,
            compact=False
        )
        if debug:
            formatted += f"\n# Debug: type={type(self).__name__}, id={id(self)}"
        return formatted
    except Exception:
        try:
            return repr(self)
        except Exception:
            return f"<unrepresentable object {type(self).__name__}>"

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    if hook is None:
        raise ValueError("hook must not be None")
    def decorator(fn):
        if not callable(fn):
            raise TypeError("handler must be callable")
        try:
            self._registry.setdefault(hook, []).append(fn)
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler for hook {hook}") from exc
        return fn
    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError("namefunc must be callable")
    def wrapper(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception:
            raise
        try:
            if sys.version_info[0] < 3:
                if isinstance(result, unicode):
                    return result.encode('utf-8')
        except NameError:
            # sys or unicode not defined, assume Python 3
            pass
        return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    default = 'unknown'

    # Try to get the distribution version via pkg_resources
    try:
        import pkg_resources
        return pkg_resources.get_distribution(__name__).version
    except Exception:
        pass

    # Try to get the distribution version via importlib.metadata (Python 3.8+)
    try:
        import importlib.metadata as metadata
        return metadata.version(__name__)
    except Exception:
        pass

    # Try to read a VERSION file in the current directory
    try:
        with open('VERSION', 'r') as f:
            return f.read().strip()
    except Exception:
        pass

    # Try to import a module named 'version' and read a VERSION or version attribute
    try:
        import importlib.util
        spec = importlib.util.find_spec('version')
        if spec is not None:
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            if hasattr(module, 'VERSION'):
                return module.VERSION
            if hasattr(module, 'version'):
                return module.version
    except Exception:
        pass

    return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    try:
        # Validate style
        if style is None:
            raise ValueError("style must be provided")
        style = style.lower()

        # Prepare components list
        if pieces is None:
            raise TypeError("pieces must not be None")
        if isinstance(pieces, (str, bytes)):
            components = [str(pieces)]
        else:
            try:
                components = [str(p) for p in pieces]
            except TypeError as e:
                raise TypeError("pieces must be an iterable of components") from e

        # Render according to style
        if style in ("short", "full"):
            return ".".join(components)
        elif style == "json":
            try:
                import json
            except ImportError as e:
                raise RuntimeError("JSON support is unavailable") from e
            return json.dumps(components)
        elif style == "list":
            return str(list(components))
        elif style == "tuple":
            return str(tuple(components))
        elif style == "dict":
            return str({i: comp for i, comp in enumerate(components)})
        elif style == "raw":
            return str(components)
        else:
            raise ValueError(f"Unsupported style: {style!r}")
    except Exception as exc:
        raise RuntimeError(
            f"Error rendering pieces {pieces!r} with style {style!r}"
        ) from exc

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if pieces is None:
        raise TypeError("pieces cannot be None")
    try:
        # Check if pieces is iterable
        iterator = iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of strings")
    # Determine if a '+' is already present
    has_plus = False
    for item in iterator:
        if item == '+':
            has_plus = True
            break
    return '.' if has_plus else '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")
    if args is None:
        args_list = []
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    else:
        raise TypeError("args must be a list or tuple of strings")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")
    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a bool")
    if not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a bool")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    # Build the full command
    full_cmd = cmd_list + args_list
    if verbose:
        print("Running command:", " ".join(full_cmd))

    # Prepare stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    # Prepare environment
    env_vars = env if env is not None else os.environ

    try:
        output = subprocess.check_output(
            full_cmd,
            cwd=cwd,
            env=env_vars,
            stderr=stderr,
            universal_newlines=True
        )
    except subprocess.CalledProcessError as e:
        # Re-raise the exception to preserve the original traceback
        raise
    except OSError as e:
        raise RuntimeError(f"Failed to execute command {full_cmd}: {e}") from e

    return output

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if 'HANDLERS' not in globals():
            globals()['HANDLERS'] = {}
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    for name, val in (('validate_objects', validate_objects),
                      ('check_digests', check_digests),
                      ('show_warnings', show_warnings)):
        if not isinstance(val, bool):
            raise TypeError(f'{name} must be a bool, got {type(val).__name__}')

    # Ensure the storage root exists
    if not hasattr(self, '_storage_root'):
        raise AttributeError('Instance has no _storage_root attribute')
    root = self._storage_root

    # Determine how to iterate over the hierarchy
    if isinstance(root, dict):
        iterable = root.items()
    elif isinstance(root, (list, tuple, set)):
        iterable = enumerate(root)
    else:
        raise TypeError('_storage_root must be a dict, list, tuple, or set')

    num_objects = 0
    good_objects = 0

    for key, obj in iterable:
        num_objects += 1
        valid = True

        # Skip None objects
        if obj is None:
            valid = False
            if show_warnings:
                print(f'Warning: object {key} is None')
            continue

        # Validate the object itself
        if validate_objects and hasattr(obj, 'validate'):
            try:
                result = obj.validate()
                if result is False:
                    valid = False
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f'Warning: object {key} failed validate() with {exc}')

        # Check the digest if requested
        if check_digests and hasattr(obj, 'check_digest'):
            try:
                result = obj.check_digest()
                if result is False:
                    valid = False
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f'Warning: object {key} failed check_digest() with {exc}')

        if valid:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os

    # Ensure the root path is defined
    root = getattr(self, "root_path", None)
    if not root:
        raise ValueError("root_path attribute is not set")

    # Resolve to an absolute path
    root = os.path.abspath(root)

    # If the root already exists, it must be empty
    if os.path.exists(root):
        if os.listdir(root):
            raise ValueError(f"Root path '{root}' already exists and is not empty")
    else:
        try:
            os.makedirs(root, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create root directory '{root}': {exc}") from exc

    # Create required subdirectories
    subdirs = ["objects", "manifests"]
    for sub in subdirs:
        sub_path = os.path.join(root, sub)
        try:
            os.makedirs(sub_path, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create subdirectory '{sub_path}': {exc}") from exc

    # Write the OCFL version file
    version_file = os.path.join(root, ".ocfl_version")
    version = getattr(self, "version", "1.0")
    try:
        with open(version_file, "w", encoding="utf-8") as f:
            f.write(f"{version}\n")
    except OSError as exc:
        raise OSError(f"Failed to write OCFL version file '{version_file}': {exc}") from exc

    # Write a marker file indicating this is an OCFL root
    root_marker = os.path.join(root, ".ocfl_root")
    try:
        with open(root_marker, "w", encoding="utf-8") as f:
            f.write("root\n")
    except OSError as exc:
        raise OSError(f"Failed to write OCFL root marker '{root_marker}': {exc}") from exc

    # Store the absolute path back on the instance for future use
    self.root_path = root
    return None

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return ""
    version = version.strip()
    if not version:
        return ""
    if not version.isdigit():
        return ""
    # Count leading zeros
    leading_zeros = len(version) - len(version.lstrip('0'))
    try:
        num = int(version)
    except Exception:
        return ""
    num += 1
    new_version = str(num)
    if leading_zeros > 0:
        width = max(len(version), len(new_version))
        new_version = new_version.zfill(width)
    return new_version

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic validation of input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    # Load the root inventory once
    try:
        with open(self.root_inventory_path, "r", encoding="utf-8") as fh:
            root_inv = json.load(fh)
    except Exception as exc:
        raise ValueError(f"Failed to load root inventory from {self.root_inventory_path!r}: {exc}")

    if not isinstance(root_inv, dict):
        raise ValueError("Root inventory must be a mapping of file paths to digests")

    # Prepare a place to record differing digests
    self.different_digests = {}

    # Keep a running set of all items that should appear up to each version
    cumulative_items = set()

    for ver_dir in version_dirs:
        inv_path = os.path.join(ver_dir, "inventory.json")
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inv = json.load(fh)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory for version directory {ver_dir!r}: {exc}")

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory in {inv_path!r} must be a mapping of file paths to digests")

        # Update cumulative set with items from this inventory
        cumulative_items.update(inv.keys())

        # Ensure that the inventory contains all items that should exist up to this point
        # (i.e., all items seen so far must be present in this inventory)
        missing = cumulative_items - set(inv.keys())
        if missing:
            raise ValueError(f"Inventory {inv_path!r} is missing items that should exist up to this version: {sorted(missing)}")

        # Record any digests that differ from the root inventory
        for path, root_digest in root_inv.items():
            inv_digest = inv.get(path)
            if inv_digest is None:
                # Missing file in this inventory – already caught by missing check
                continue
            if inv_digest != root_digest:
                self.different_digests.setdefault(path, []).append(ver_dir)

    return self

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")
    if bug_ids is None:
        return params
    # Convert bug_ids to a comma‑separated string
    if isinstance(bug_ids, (list, tuple, set)):
        ids_str = ','.join(str(b) for b in bug_ids)
    else:
        ids_str = str(bug_ids)
    # Merge with any existing 'ids' entry
    if 'ids' in params:
        existing = params['ids']
        if isinstance(existing, (list, tuple, set)):
            existing_str = ','.join(str(b) for b in existing)
        else:
            existing_str = str(existing)
        combined = ','.join(filter(None, [existing_str, ids_str]))
        params['ids'] = combined
    else:
        params['ids'] = ids_str
    return params

def parse_arguments(*arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    """
    parser = argparse.ArgumentParser(description='Command-line arguments for the script.')
    try:
        if arguments:
            return parser.parse_args(list(arguments))
        else:
            return parser.parse_args()
    except SystemExit as e:
        raise ValueError(f"Argument parsing failed: {e}") from e

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Basic validation: ensure parser has the expected attribute
    if parser is None or not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = []
    for action in parser._actions:
        # Each action may have an option_strings attribute (list of flag strings)
        option_strings = getattr(action, "option_strings", [])
        if option_strings:
            flags.extend(option_strings)

    return " ".join(flags)

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    # Create a top-level parser and a subparsers container.
    parser = argparse.ArgumentParser()
    parser.add_subparsers(dest='subparser_name')
    try:
        namespace, _ = parser.parse_known_args(unparsed_arguments)
    except Exception as exc:
        raise ValueError(f"Error parsing arguments: {exc}") from exc

    result = {}
    subparser_name = getattr(namespace, 'subparser_name', None)
    if subparser_name:
        result[subparser_name] = namespace
    else:
        result['global'] = namespace
    return result

def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string."""
    # Validate that the parser has the expected attribute
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = []
    for action in actions:
        # Each action may have an option_strings attribute containing the flag names
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            flags.extend(option_strings)

    return " ".join(flags)

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import click
        from borgmatic.cli.main import main as borgmatic_main
    except Exception as exc:
        raise RuntimeError(f"Failed to import required modules for completion: {exc}")

    try:
        # click 8+ provides a helper to generate a completion script
        if hasattr(click.shell_completion, "get_completion_script"):
            script = click.shell_completion.get_completion_script(borgmatic_main, shell="bash")
        else:
