def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    for i in range(0, len(response), max_results):
        yield response[i:i + max_results]

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Expected an iterable of dictionaries, got None")
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError(f"Expected an iterable of dictionaries, got {type(dicts).__name__}")
    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError(f"Expected each element to be a dict, got {type(d).__name__}")
        for key, value in d.items():
            try:
                result[key] = result.get(key, 0) + value
            except TypeError as exc:
                raise TypeError(f"Cannot add values for key {key!r}: {exc}") from exc
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not isinstance(url, str):
        return url
    if not url:
        return ''
    if not url_args:
        return url
    if not hasattr(url_args, 'items'):
        raise TypeError('url_args must be a mapping')
    result = url
    for key, value in url_args.items():
        key_str = str(key)
        placeholder_curly = '{' + key_str + '}'
        placeholder_colon = ':' + key_str
        if value is None:
            replacement = ''
        else:
            replacement = str(value)
        if placeholder_curly in result:
            result = result.replace(placeholder_curly, replacement)
        if placeholder_colon in result:
            result = result.replace(placeholder_colon, replacement)
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # None itself is considered a None value
    if val is None:
        return True
    # Only strings can represent a None value in this context
    if not isinstance(val, str):
        return False
    # Strip whitespace for accurate comparison
    stripped = val.strip()
    # Empty string or common textual representations of None
    if not stripped:
        return True
    if stripped.lower() in {"none", "null", "na", "n/a", "nil"}:
        return True
    return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate that the parser has the expected attribute
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = []
    for action in actions:
        # Only include actions that define option strings (i.e., flags)
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            flags.extend(option_strings)

    return " ".join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two distinct symbols")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique symbols")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)
    digits = []

    # Special case for zero
    if number == 0:
        digits.append(alphabet[0])
    else:
        while number > 0:
            digits.append(alphabet[number % base])
            number //= base

    # Most significant digit first
    digits.reverse()

    # Apply padding if requested
    if padding is not None and len(digits) < padding:
        pad_len = padding - len(digits)
        digits = [alphabet[0]] * pad_len + digits

    return ''.join(digits)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""

    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError("Expected a class type, got %r" % (cls,))
    seen = set()
    queue = [cls]
    while queue:
        parent = queue.pop()
        try:
            children = parent.__subclasses__()
        except Exception:
            continue
        for child in children:
            if child not in seen:
                seen.add(child)
                queue.append(child)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")

    # Validate alphabet contents
    if len(alphabet) == 0:
        raise ValueError("alphabet must contain at least one character")
    for idx, ch in enumerate(alphabet):
        if not isinstance(ch, str) or len(ch) != 1:
            raise TypeError(f"alphabet element at index {idx} must be a single-character string")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet contains duplicate characters")

    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two unique characters")

    # Build mapping from character to its numeric value
    mapping = {ch: i for i, ch in enumerate(alphabet)}

    # Validate string
    if string == "":
        raise ValueError("string must not be empty")

    # Convert string to integer
    result = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"character '{ch}' not found in alphabet")
        result = result * base + mapping[ch]

    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Remove leading and trailing matching quotes (single or double)
    return re.sub(r"^(['\"])(.*)\1$", r"\2", name)

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stderr=subprocess.STDOUT,
            universal_newlines=True
        )
    except subprocess.CalledProcessError:
        return ''
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = frequency.strip()
    if freq.lower() == "always":
        return None

    import re
    m = re.match(r'^(\d+)\s*([a-zA-Z]+)$', freq)
    if not m:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")

    num = int(m.group(1))
    unit = m.group(2).lower()

    if unit in ('day', 'days'):
        return datetime.timedelta(days=num)
    if unit in ('week', 'weeks'):
        return datetime.timedelta(weeks=num)
    if unit in ('hour', 'hours'):
        return datetime.timedelta(hours=num)
    if unit in ('minute', 'minutes'):
        return datetime.timedelta(minutes=num)
    if unit in ('second', 'seconds'):
        return datetime.timedelta(seconds=num)
    if unit in ('month', 'months'):
        return datetime.timedelta(days=num * 30)
    if unit in ('year', 'years'):
        return datetime.timedelta(days=num * 365)

    raise ValueError(f"Unknown time unit in frequency: {unit!r}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in infos:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip == '127.0.0.1':
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            # strip zone index if present
            ip = ip.split('%')[0]
            if ip == '::1':
                return True
    return False

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if find_paths is None:
        raise TypeError("find_paths cannot be None")
    # Ensure we have an iterable of strings (or convertible to string)
    try:
        iterator = iter(find_paths)
    except TypeError:
        raise TypeError(f"find_paths must be an iterable, got {type(find_paths)}")
    transformed = []
    for item in iterator:
        if not isinstance(item, str):
            # Convert non-string items to string representation
            item_str = str(item)
        else:
            item_str = item
        # If the item contains a colon, treat it as an existing pattern and leave unchanged
        if ':' in item_str:
            transformed.append(item_str)
        else:
            # Wrap the fragment into a glob pattern with the default 'sh' scheme
            transformed.append(f'sh:**/*{item_str}*/**')
    return transformed

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if pattern is None:
        return None
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    # Handle compiled regex objects
    if hasattr(re, 'Pattern') and isinstance(pattern, re.Pattern):
        return pattern
    if hasattr(re, '_pattern_type') and isinstance(pattern, re._pattern_type):
        return pattern
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate commands
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a list or tuple of command parts")
    # Validate args
    if args is None:
        args = []
    if isinstance(args, str):
        args = [args]
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of arguments")
    # Build command
    cmd = list(commands) + list(args)
    if verbose:
        print("Running command:", " ".join(map(str, cmd)))
    # Set stderr
    stderr = subprocess.DEVNULL if hide_stderr else None
    try:
        result = subprocess.run(cmd, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=stderr, text=True, check=True)
    except subprocess.CalledProcessError as e:
        # Re-raise with context
        raise subprocess.CalledProcessError(e.returncode, e.cmd, output=e.output, stderr=e.stderr)
    return result

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        addr = ipaddress.ip_address(target)
    except ValueError:
        return False
    return isinstance(addr, ipaddress.IPv4Address)

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = yaml.SafeDumper
    try:
        s = yaml.safe_dump(obj, Dumper=dumper, default_flow_style=False)
    except Exception as exc:
        raise
    import sys
    if sys.version_info[0] < 3 and isinstance(s, bytes):
        s = s.decode('utf-8')
    return s

def build_app_logger(name='app', logfile='app.log', debug=True):
    """General purpose application logger. Useful mainly for debugging"""
    # Validate input types
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(logfile, str):
        raise TypeError("logfile must be a string")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    if not name:
        raise ValueError("name cannot be empty")
    if not logfile:
        raise ValueError("logfile cannot be empty")

    logger = logging.getLogger(name)
    level = logging.DEBUG if debug else logging.INFO
    logger.setLevel(level)
    logger.propagate = False

    # If handlers already exist, return the logger to avoid duplicates
    if logger.handlers:
        return logger

    # Ensure the directory for the logfile exists
    log_dir = os.path.dirname(os.path.abspath(logfile))
    if log_dir and not os.path.exists(log_dir):
        try:
            os.makedirs(log_dir, exist_ok=True)
        except Exception:
            # If directory creation fails, we simply proceed; file handler may fail later
            pass

    formatter = logging.Formatter(
        '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
    )

    # File handler
    try:
        fh = logging.FileHandler(logfile, mode='a')
        fh.setLevel(level)
        fh.setFormatter(formatter)
        logger.addHandler(fh)
    except Exception:
        # If file handler cannot be created, skip it
        pass

    # Stream handler (stdout)
    try:
        sh = logging.StreamHandler()
        sh.setLevel(level)
        sh.setFormatter(formatter)
        logger.addHandler(sh)
    except Exception:
        # If stream handler cannot be created, skip it
        pass

    return logger

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import yaml
    import toml
    import logging

    config_map = {}
    error_records = []

    def _make_error_record(filename, message, exc=None):
        # Create a LogRecord for the error
        record = logging.LogRecord(
            name='config_loader',
            level=logging.ERROR,
            pathname=filename,
            lineno=0,
            msg=message,
            args=(),
            exc_info=exc
        )
        return record

    def _resolve_env_in_value(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        return value

    def _resolve_env_in_dict(d):
        if isinstance(d, dict):
            return {k: _resolve_env_in_dict(_resolve_env_in_value(v)) for k, v in d.items()}
        elif isinstance(d, list):
            return [_resolve_env_in_dict(_resolve_env_in_value(v)) for v in d]
        else:
            return _resolve_env_in_value(d)

    for filename in config_filenames:
        try:
            if not os.path.isfile(filename):
                raise FileNotFoundError(f"Configuration file not found: {filename}")

            with open(filename, 'r', encoding='utf-8') as f:
                raw = f.read()

            # Determine parser based on extension
            ext = os.path.splitext(filename)[1].lower()
            if ext in {'.toml', '.tml'}:
                parsed = toml.loads(raw)
            elif ext in {'.yaml', '.yml'}:
                parsed = yaml.safe_load(raw)
            elif ext in {'.json'}:
                parsed = json.loads(raw)
            else:
                # Try all parsers in order
                try:
                    parsed = toml.loads(raw)
                except Exception:
                    try:
                        parsed = yaml.safe_load(raw)
                    except Exception:
                        parsed = json.loads(raw)

            if not isinstance(parsed, dict):
                raise ValueError(f"Parsed configuration is not a dictionary: {filename}")

            if overrides:
                # shallow merge overrides into parsed config
                parsed.update(overrides)

            if resolve_env:
                parsed = _resolve_env_in_dict(parsed)

            config_map[filename] = parsed

        except Exception as exc:
            msg = f"Error loading configuration '{filename}': {exc}"
            error_records.append(_make_error_record(filename, msg, exc_info=exc))

    return config_map, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    try:
        if isinstance(obj, str):
            return obj.encode('utf-8')
        else:
            return obj
    except Exception as exc:
        raise ValueError(f"Failed to encode object to bytes: {exc}") from exc

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        # Prefer a pre‑defined mapping if available
        if hasattr(cls, "PROTOCOL_HANDLERS") and isinstance(cls.PROTOCOL_HANDLERS, dict):
            handlers = dict(cls.PROTOCOL_HANDLERS)  # shallow copy to avoid accidental mutation
        else:
            # Discover handler classes defined within the class that expose a _protocol_version attribute
            handlers = {}
            for obj in cls.__dict__.values():
                if isinstance(obj, type) and hasattr(obj, "_protocol_version"):
                    ver = getattr(obj, "_protocol_version")
                    if isinstance(ver, tuple):
                        handlers[ver] = obj

        if protocol_version is not None:
            return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}
        return handlers

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("values cannot be None")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")
    raw_bookmarks = []
    for v in iterator:
        if not isinstance(v, str):
            raise TypeError(f"bookmark value must be a string, got {type(v).__name__}")
        raw_bookmarks.append(v)
    return cls(raw_bookmarks)

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate get_coordinate
    if not isinstance(get_coordinate, str):
        raise TypeError("get_coordinate must be a string")
    coord_type = get_coordinate.lower()
    if coord_type not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    # Resolve scale
    if scale is None:
        scale = getattr(hist, "scale", None)
    elif scale is True:
        scale = getattr(hist, "scale", None)

    # Retrieve bin edges and contents
    edges = getattr(hist, "edges", None)
    if edges is None:
        edges = getattr(hist, "bin_edges", None)
    if edges is None:
        raise AttributeError("hist must have an 'edges' or 'bin_edges' attribute")

    contents = getattr(hist, "bins", None)
    if contents is None:
        contents = getattr(hist, "bin_contents", None)
    if contents is None:
        raise AttributeError("hist must have a 'bins' or 'bin_contents' attribute")

    # Ensure lengths are consistent
    if len(edges) != len(contents) + 1:
        raise ValueError("Number of edges must be one more than number of bins")

    # Build graph points
    points = []
    for i, bin_content in enumerate(contents):
        if coord_type == "left":
            coord = edges[i]
        elif coord_type == "right":
            coord = edges[i + 1]
        else:  # middle
            coord = (edges[i] + edges[i + 1]) / 2

        if make_value is None:
            value = bin_content
        else:
            value = make_value(bin_content)

        # Ensure value is a tuple/list for unpacking
        if isinstance(value, (tuple, list)):
            val_tuple = tuple(value)
        else:
            val_tuple = (value,)

        point = (coord, *val_tuple)
        points.append(point)

    # Validate field_names length
    if not isinstance(field_names, (tuple, list)):
        raise TypeError("field_names must be a tuple or list")
    if len(field_names) != (len(points[0]) if points else 0):
        raise ValueError("field_names length must match the dimension of the result")

    # Attempt to construct a Graph object if available
    graph = None
    GraphCls = None
    try:
        GraphCls = globals()["Graph"]
    except KeyError:
        try:
            GraphCls = locals()["Graph"]
        except KeyError:
            GraphCls = None

    if GraphCls is not None:
        try:
            # Try constructor with data, field_names, scale
            graph = GraphCls(points, field_names=field_names, scale=scale)
        except TypeError:
            try:
                graph = GraphCls(field_names=field_names, scale=scale)
                if hasattr(graph, "add_points"):
                    graph.add_points(points)
                else:
                    # Fallback: set data attribute
                    graph.data = points
            except Exception:
                # If all fails, fall back to dict
                graph = None

    if graph is None:
        # Fallback representation
        graph = {"data": points, "field_names": tuple(field_names), "scale": scale}

    return graph

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate that all bases are types
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"Base {b!r} is not a type")
    # If an explicit metaclass is supplied, it must be a type
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass {explicit_mc!r} is not a type")
        # The explicit metaclass must be compatible with all base metaclasses
        for b in bases:
            base_meta = type(b)
            if not issubclass(explicit_mc, base_meta):
                raise TypeError(
                    f"Explicit metaclass {explicit_mc.__name__} is not compatible "
                    f"with base {b.__name__} (metaclass {base_meta.__name__})"
                )
        return explicit_mc
    # No explicit metaclass: determine the most derived metaclass from bases
    if not bases:
        return type
    metaclasses = [type(b) for b in bases]
    # Find a metaclass that is a subclass of all others
    candidate = None
    for mc in metaclasses:
        if all(issubclass(mc, other) for other in metaclasses):
            if candidate is not None:
                raise TypeError(
                    "Metaclass conflict: multiple most derived metaclasses found"
                )
            candidate = mc
    if candidate is None:
        raise TypeError(
            "Metaclass conflict: no unique most derived metaclass could be found"
        )
    return candidate

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        # Assuming `self._cache` is an OrderedDict that keeps insertion order
        # with the least recently used item at the beginning.
        key, value = self._cache.popitem(last=False)
    except KeyError:
        # If the cache is empty, raise a KeyError to match dict behavior.
        raise KeyError('cache is empty')
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        return dict.popitem(self)
    except KeyError:
        raise KeyError('dict is empty')

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('dictionary is empty')
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    return _converting._Converter()

def isoparse(self, dt_str):
    """Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    Supports a wide range of ISO-8601 date and time formats, including
    year-only, year-month, year-month-day, ISO week dates, and various
    time zone representations. Unspecified components default to their
    lowest values. 24:00 is treated as midnight of the following day.
    """
    import re
    from datetime import datetime, date, time, timedelta
    from dateutil.tz import tzutc, tzoffset

    if not isinstance(dt_str, (str, bytes)):
        raise TypeError("dt_str must be a string or bytes")
    if isinstance(dt_str, bytes):
        try:
            dt_str = dt_str.decode("ascii")
        except Exception as exc:
            raise ValueError("bytes input must be ASCII") from exc

    # Split date and time
    if 'T' in dt_str:
        date_part, time_part = dt_str.split('T', 1)
    else:
        date_part, time_part = dt_str, None

    # ---------- Parse date ----------
    # Patterns
    # year only
    m = re.fullmatch(r'(?P<year>\d{4})', date_part)
    if m:
        year = int(m.group('year'))
        month = 1
        day = 1
    else:
        # year-month or yearmonth
        m = re.fullmatch(r'(?P<year>\d{4})[-]?(?P<month>\d{2})', date_part)
        if m:
            year = int(m.group('year'))
            month = int(m.group('month'))
            day = 1
        else:
            # year-month-day or yearmonthday
            m = re.fullmatch(r'(?P<year>\d{4})[-]?(?P<month>\d{2})[-]?(?P<day>\d{2})', date_part)
            if m:
                year = int(m.group('year'))
                month = int(m.group('month'))
                day = int(m.group('day'))
            else:
                # ISO week: YYYY-Www or YYYYWww
                m = re.fullmatch(r'(?P<year>\d{4})[-]?(?P<week>\d{2})', date_part.replace('W', '-W'))
                if m:
                    year = int(m.group('year'))
                    week = int(m.group('week'))
                    day = 1  # default to Monday
                    try:
                        d = date.fromisocalendar(year, week, day)
                    except Exception as exc:
                        raise ValueError(f"Invalid ISO week date: {date_part}") from exc
                    year, month, day = d.year, d.month, d.day
                else:
                    # ISO week with day: YYYY-Www-D or YYYYWwwD
                    m = re.fullmatch(r'(?P<year>\d{4})[-]?(?P<week>\d{2})[-]?(?P<weekday>\d)', date_part.replace('W', '-W'))
                    if m:
                        year = int(m.group('year'))
                        week = int(m.group('week'))
                        weekday = int(m.group('weekday'))
                        try:
                            d = date.fromisocalendar(year, week, weekday)
                        except Exception as exc:
                            raise ValueError(f"Invalid ISO week date: {date_part}") from exc
                        year, month, day = d.year, d.month, d.day
                    else:
                        raise ValueError(f"Unrecognized date format: {date_part}")

    # ---------- Parse time ----------
    hour = minute = second = microsecond = 0
    tzinfo = None
    if time_part:
        # Separate timezone
        tz_match = re.search(r'(Z|[+-]\d{2}(:?\d{2})?)$', time_part)
        if tz_match:
            tz_str = tz_match.group(0)
            time_str = time_part[:tz_match.start()]
        else:
            tz_str = None
            time_str = time_part

        # Parse time components
        # hh, hh:mm, hhmm, hh:mm:ss, hhmmss, hh:mm:ss.ssssss, hhmmss.ssssss
        # Allow dot or comma as decimal separator
        time_re = re.compile(
            r'^(?P<hour>\d{2})'
            r'(?:[:](?P<minute>\d{2})'
            r'(?:[:](?P<second>\d{2})'
            r'(?:[.,](?P<fraction>\d{1,6}))?)?)?$'
        )
        m = time_re.match(time_str)
        if not m:
            # Try compact form without separators
            m = re.match(r'^(?P<hour>\d{2})(?P<minute>\d{2})?(?P<second>\d{2})?(?:[.,](?P<fraction>\d{1,6}))?$', time_str)
            if not m:
                raise ValueError(f"Unrecognized time format: {time_str}")
        hour = int(m.group('hour'))
        minute = int(m.group('minute') or 0)
        second = int(m.group('second') or 0)
        fraction = m.group('fraction')
        if fraction:
            microsecond = int(fraction.ljust(6, '0'))
        # Handle 24:00:00
        if hour == 24 and minute == 0 and second == 0:
            hour = 0
            # add one day to date
            try:
                d = date(year, month, day) + timedelta(days=1)
                year, month, day = d.year, d.month, d.day
            except Exception as exc:
                raise ValueError("Invalid date for 24:00 time") from exc

        # Parse timezone
        if tz_str:
            if tz_str == 'Z':
                tzinfo = tzutc()
            else:
                # +/-HH:MM or +/-HHMM or +/-HH
                sign = 1 if tz_str[0] == '+' else -1
                tz_body = tz_str[1:]
                if ':' in tz_body:
                    h, m_ = tz_body.split(':')
                else:
                    if len(tz_body) == 4:
                        h, m_ = tz_body[:2], tz_body[2:]
                    else:
                        h, m_ = tz_body, '0'
                try:
                    offset_hours = int(h)
                    offset_minutes = int(m_)
                except Exception as exc:
                    raise ValueError(f"Invalid timezone offset: {tz_str}") from exc
                offset_seconds = sign * (offset_hours * 3600 + offset_minutes * 60)
                if offset_seconds == 0:
                    tzinfo = tzutc()
                else:
                    tzinfo = tzoffset(None, offset_seconds)

    # ---------- Construct datetime ----------
    try:
        dt = datetime(year, month, day, hour, minute, second, microsecond, tzinfo=tzinfo)
    except Exception as exc:
        raise ValueError(f"Failed to construct datetime from components: {exc}") from exc

    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # 1. Check the request path – Matrix endpoints usually start with "/_matrix"
        path = getattr(request, "path", None) or getattr(request, "url", None)
        if isinstance(path, str) and path.startswith("/_matrix"):
            return True

        # 2. Check headers for typical Matrix content type
        headers = None
        if hasattr(request, "headers"):
            # Flask/Django request.headers is a dict-like object
            headers = request.headers
        elif hasattr(request, "META"):
            # Django request.META contains HTTP headers with 'HTTP_' prefix
            headers = request.META

        if headers:
            # Normalize header lookup
            content_type = None
            if isinstance(headers, dict):
                content_type = headers.get("Content-Type") or headers.get("content-type")
            else:
                # Assume a dict-like interface
                content_type = headers.get("Content-Type")
            if content_type and "application/json" in content_type.lower():
                return True

        # 3. Fallback: if the request has a body that looks like JSON
        if hasattr(request, "data"):
            try:
                import json
                json.loads(request.data)
                return True
            except Exception:
                pass

        return False
    except Exception:
        # In case of any unexpected attribute errors or other issues, conservatively
        # return False to avoid false positives.
        return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if dt is None:
        return None
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime instance")
    # Convert to UTC
    if dt.tzinfo is None:
        # Assume naive datetime is already UTC
        dt_utc = dt
    else:
        dt_utc = dt.astimezone(datetime.timezone.utc)
    # Return ISO 8601 string without microseconds
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        scheme, netloc, path, query, fragment = urllib.parse.urlsplit(url)
    except Exception:
        return None
    if scheme not in ("http", "https"):
        return None
    req = urllib.request.Request(url, method="HEAD")
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            if hasattr(resp, "status") and resp.status != 200:
                return None
            return resp.getheader("Content-Type")
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Ensure the input is a string
    if not isinstance(tag, str):
        return False

    # Strip leading/trailing whitespace
    tag = tag.strip()

    # Reject empty strings
    if not tag:
        return False

    # Optional length limit (e.g., 30 characters)
    if len(tag) > 30:
        return False

    # Tag must consist of alphanumeric characters, hyphens, or underscores only
    for ch in tag:
        if not (ch.isalnum() or ch in ('-', '_')):
            return False

    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an ElementTree element") from exc

    result = {}
    for child in children:
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    # Ensure the URL has a scheme
    if not url.startswith(("http://", "https://")):
        raise ValueError("url must start with http:// or https://")
    # Strip trailing slash to avoid double slashes when concatenating
    base = url.rstrip("/")
    # Determine the document path
    if document_path is None:
        path = "/.well-known/nodeinfo/1.0"
    else:
        if not isinstance(document_path, str):
            raise TypeError("document_path must be a string if provided")
        # Ensure the path starts with a slash
        path = document_path if document_path.startswith("/") else "/" + document_path
    # Construct the full href
    href = f"{base}{path}"
    # Build the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        import lxml.etree as ET
        import xmlsec
    except Exception:
        # Required libraries are not available
        return False

    if not doc or not signature:
        return False

    # Parse the XML document
    try:
        root = ET.fromstring(doc)
    except ET.XMLSyntaxError:
        return False

    # Namespace for XML Signature
    ns = {'ds': 'http://www.w3.org/2000/09/xmldsig#'}

    # Find the Signature element
    sig_elem = root.find('.//ds:Signature', namespaces=ns)
    if sig_elem is None:
        return False

    # Verify that the provided signature string matches the SignatureValue
    sig_value_elem = sig_elem.find('.//ds:SignatureValue', namespaces=ns)
    if sig_value_elem is None or not sig_value_elem.text:
        return False
    if sig_value_elem.text.strip() != signature.strip():
        return False

    # Load the public key
    key = None
    try:
        # Try loading from a file path
        key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM)
    except Exception:
        try:
            # Try loading from a PEM string
            key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
        except Exception:
            return False

    # Create a verification context
    try:
        ctx = xmlsec.SignatureContext()
        ctx.key = key
    except Exception:
        return False

    # Perform the verification
    try:
        ctx.verify(sig_elem)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        return None
    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            result = {}
            # Preserve subject if present
            if "subject" in data:
                result["subject"] = data["subject"]
            links = data.get("links", [])
            for link in links:
                if not isinstance(link, dict):
                    continue
                rel = link.get("rel")
                if not rel:
                    continue
                href = link.get("href") or link.get("template")
                if not href:
                    continue
                # If multiple links with same rel, store as list
                if rel in result:
                    if isinstance(result[rel], list):
                        result[rel].append(href)
                    else:
                        result[rel] = [result[rel], href]
                else:
                    result[rel] = href
            return result
    except Exception:
        # Not JSON, fall back to XRD
        pass

    # Try XRD (XML)
    try:
        root = ET.fromstring(document)
        result = {}
        # Extract subject if present
        subject = root.findtext(".//{*}Subject")
        if subject:
            result["subject"] = subject
        # Find all Link elements
        for link in root.findall(".//{*}Link"):
            rel = link.get("rel")
            if not rel:
                continue
            href = link.get("href") or link.get("template")
            if not href:
                continue
            if rel in result:
                if isinstance(result[rel], list):
                    result[rel].append(href)
                else:
                    result[rel] = [result[rel], href]
            else:
                result[rel] = href
        if result:
            return result
    except Exception:
        pass

    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    lrdd_link = hostmeta.find_link(rels="lrdd")
    if not lrdd_link:
        return None
    url = lrdd_link.template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    # Validate the dictionary
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")

    # Validate the first key
    if key is None:
        raise ValueError("key cannot be None")
    try:
        hash(key)
    except TypeError:
        raise TypeError("key must be hashable")

    # Validate any additional keys
    for k in keys:
        if k is None:
            raise ValueError("keys cannot contain None")
        try:
            hash(k)
        except TypeError:
            raise TypeError("all keys must be hashable")

    # Build the full key chain
    chain = (key,) + keys

    # If only one key, set it directly
    if len(chain) == 1:
        dic[chain[0]] = val
        return

    # Traverse or create intermediate dictionaries
    current = dic
    for k in chain[:-1]:
        if k in current:
            if not isinstance(current[k], dict):
                raise TypeError(f"Intermediate key '{k}' is not a dictionary")
        else:
            current[k] = {}
        current = current[k]

    # Set the final key to the value
    current[chain[-1]] = val

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Ensure settings_dirs is iterable
        if not isinstance(settings_dirs, (list, tuple)):
            settings_dirs = [settings_dirs]
        file_list = []
        for directory in settings_dirs:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                if spec_option and not fname.endswith(spec_option):
                    continue
                file_list.append(os.path.join(directory, fname))
        return sorted(file_list)
    except Exception:
        return []

