@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Ensure content is provided
        if spec_content is None:
            raise IRValidatorException("spec_content must be provided")

        # If spec_content is a file-like object, read its content
        if hasattr(spec_content, "read"):
            try:
                spec_content = spec_content.read()
            except Exception as exc:
                raise IRValidatorException(f"Unable to read spec content: {exc}")

        # If spec_content is bytes, decode to string
        if isinstance(spec_content, bytes):
            try:
                spec_content = spec_content.decode("utf-8")
            except Exception as exc:
                raise IRValidatorException(f"Unable to decode spec content: {exc}")

        # Parse YAML
        try:
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"YAML parsing error: {exc}")

        # Basic validation: data must be a dict
        if not isinstance(data, dict):
            raise IRValidatorException("Spec content must be a YAML mapping (dictionary)")

        # Define required fields (adjust as needed for your spec)
        required_fields = ["name", "type", "spec"]
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required field(s): {', '.join(missing)}")

        return data

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")

    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as e:
        raise IRValidatorException(f"File not found: {yaml_file}") from e
    except Exception as e:
        raise IRValidatorException(f"Error loading YAML file: {e}") from e

    if data is None:
        raise IRValidatorException("YAML file is empty or contains no data")

    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a mapping at the top level")

    # Define the mandatory fields that must be present in the YAML file.
    # Adjust this list as needed for your specific schema.
    required_fields = ["name", "version", "data"]

    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    import os
    import json
    try:
        import yaml
    except Exception:
        yaml = None

    processed_paths = set()

    def _load_spec(path):
        abs_path = os.path.abspath(path)
        if abs_path in processed_paths:
            return {}
        processed_paths.add(abs_path)
        try:
            with open(abs_path, 'r') as f:
                if abs_path.endswith('.json'):
                    data = json.load(f)
                else:
                    if yaml is None:
                        raise RuntimeError(f"YAML support not available for {abs_path}")
                    data = yaml.safe_load(f)
        except Exception as e:
            raise RuntimeError(f"Failed to load spec file {abs_path}: {e}")
        if not isinstance(data, dict):
            raise ValueError(f"Spec file {abs_path} does not contain a dict")
        # Resolve includes in the loaded spec
        self._include_groups(data)
        return data

    # Work on a copy of keys to avoid modification during iteration
    for parser_name, spec in list(parser_dict.items()):
        if not isinstance(spec, dict):
            continue
        include = spec.pop('include', None)
        if include is None:
            continue
        if isinstance(include, str):
            included = _load_spec(include)
            for k, v in included.items():
                if k not in parser_dict:
                    parser_dict[k] = v
        elif isinstance(include, dict):
            for k, path in include.items():
                included = _load_spec(path)
                if k in included:
                    parser_dict[k] = included[k]
                else:
                    raise KeyError(f"Included spec {path} does not contain parser {k}")
        elif isinstance(include, list):
            for path in include:
                included = _load_spec(path)
                for k, v in included.items():
                    if k not in parser_dict:
                        parser_dict[k] = v
        else:
            raise TypeError(f"Unsupported include type: {type(include)} for parser {parser_name}")

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in getattr(self, "args", []):
        # Skip non-option objects
        if not isinstance(arg, _BaseOpt):
            continue

        # Attempt to get a value from the spec first
        spec_val = None
        try:
            spec_val = self.spec.get(arg.name)
        except Exception:
            # If spec is not a dict-like or missing, ignore and fall back
            pass

        if spec_val is not None:
            defaults[arg.name] = spec_val
        else:
            # Fall back to the option's own default if it exists
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

        # Handle nested dictionary options by recursing into their scheme
        if isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[arg.name] = nested

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Mapping of deprecated argument names to their replacements.
    # Subclasses or instances may define this attribute.
    deprecated = getattr(self, 'deprecated_args', {})
    # Merge the two dictionaries for a unified view of supplied arguments.
    merged = {**answer_file_args, **cli_args}
    for old_name, new_name in deprecated.items():
        if old_name in merged:
            if new_name in merged:
                raise ValueError(
                    f"Both deprecated argument '{old_name}' and its replacement "
                    f"'{new_name}' were provided."
                )
            # Emit a warning for the deprecated argument.
            print(
                f"Warning: argument '{old_name}' is deprecated. "
                f"Use '{new_name}' instead."
            )

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input type
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Retrieve the internal mapping of command options
    try:
        command_options = getattr(self, "_command_options", {})
    except Exception as exc:
        raise RuntimeError("Unable to access command options mapping") from exc

    # Ensure the command exists
    if command_name not in command_options:
        raise KeyError(f"Command '{command_name}' not found in parser options")

    # Return a copy to prevent accidental mutation of internal state
    options = command_options[command_name]
    if isinstance(options, (list, tuple)):
        return list(options)
    # If options are stored in another iterable type, convert to list
    try:
        return list(options)
    except TypeError:
        # If options is a single object, wrap it in a list
        return [options] if options is not None else []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Ensure the internal specification dictionary exists
    if not hasattr(self, "_specs"):
        raise AttributeError("Option specifications not initialized on this instance.")

    # Retrieve the command‑level specification
    cmd_spec = self._specs.get(command_name)
    if cmd_spec is None:
        # Command not found – return None to indicate missing spec
        return None

    # If no specific argument requested, return the whole command spec
    if argument_name is None:
        return cmd_spec

    # Return the argument specification if it exists, otherwise None
    return cmd_spec.get(argument_name)

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a mapping of argument names to values
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    # Retrieve the list of required argument names
    required = getattr(self, "required_args", None)
    if required is None:
        raise AttributeError("The instance does not define a 'required_args' attribute")

    if not hasattr(required, "__iter__"):
        raise TypeError("'required_args' must be an iterable of argument names")

    # Identify any missing required arguments
    missing = [name for name in required if name not in args or args[name] is None]

    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    if not options_spec:
        return required
    for opt in options_spec:
        # opt may be a dict or an object with attributes
        required_when = None
        name = None
        if isinstance(opt, dict):
            required_when = opt.get('required_when')
            name = opt.get('name')
        else:
            required_when = getattr(opt, 'required_when', None)
            name = getattr(opt, 'name', None)
        if name is None:
            continue
        if required_when is None:
            continue
        try:
            if callable(required_when):
                matched = required_when(command_name, args)
            else:
                # Treat as a string expression; evaluate in a safe namespace
                matched = eval(
                    required_when,
                    {},
                    {'command_name': command_name, 'args': args}
                )
            if matched:
                required.append(name)
        except Exception:
            # If evaluation fails, ignore this option
            continue
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions from the parsed YAML configuration
    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, arg_value in args.items():
        # Get the expected maximum length for this argument, if any
        arg_def = arg_defs.get(arg_name, {})
        max_len = arg_def.get('length')
        if max_len is None:
            # No length constraint specified; skip validation
            continue

        # Validate that the maximum length is a non‑negative integer
        if not isinstance(max_len, int):
            raise TypeError(
                f"Length for argument '{arg_name}' must be an integer (got {type(max_len).__name__})"
            )
        if max_len < 0:
            raise ValueError(
                f"Length for argument '{arg_name}' must be non‑negative (got {max_len})"
            )

        # Skip validation for None values
        if arg_value is None:
            continue

        # Attempt to determine the length of the provided value
        try:
            actual_len = len(arg_value)
        except TypeError:
            raise TypeError(
                f"Argument '{arg_name}' does not support len() and cannot be validated against a length constraint"
            )

        # Raise an error if the actual length exceeds the allowed maximum
        if actual_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {actual_len} exceeds the maximum allowed length of {max_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict of argument values")
    # Retrieve argument definitions; fall back to parsed_yaml if not explicitly set
    arg_defs = getattr(self, 'arg_definitions', None)
    if arg_defs is None:
        arg_defs = getattr(self, 'parsed_yaml', {}).get('args', {})
    for arg_name, value in args.items():
        # Locate the definition for this argument
        definition = None
        if isinstance(arg_defs, dict):
            definition = arg_defs.get(arg_name)
        elif isinstance(arg_defs, list):
            for item in arg_defs:
                if isinstance(item, dict):
                    for k, v in item.items():
                        if k == arg_name:
                            definition = v
                            break
                if definition:
                    break
        if not definition:
            continue
        # If the argument has a 'choices' attribute, validate the value
        choices = definition.get('choices')
        if choices is None:
            continue
        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{arg_name}': {value}. "
                f"Expected one of {choices}."
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Helper to validate a single value against optional bounds
    def _check_value(name, value, min_val, max_val):
        if value is None:
            return
        if min_val is not None and value < min_val:
            raise ValueError(
                f"Argument '{name}' value {value} below minimum {min_val}"
            )
        if max_val is not None and value > max_val:
            raise ValueError(
                f"Argument '{name}' value {value} above maximum {max_val}"
            )

    # If args is a mapping, validate each key/value pair
    if isinstance(args, dict):
        for key, value in args.items():
            min_attr = getattr(self, f"min_{key}", None)
            max_attr = getattr(self, f"max_{key}", None)
            _check_value(key, value, min_attr, max_attr)
        return args

    # If args is an iterable (but not a string/bytes), validate each element
    if isinstance(args, (list, tuple, set, frozenset)):
        # Use generic min/max attributes if defined
        min_val = getattr(self, "min", None)
        max_val = getattr(self, "max", None)
        for idx, value in enumerate(args):
            _check_value(idx, value, min_val, max_val)
        return args

    # Otherwise treat args as a single value
    min_val = getattr(self, "min", None)
    max_val = getattr(self, "max", None)
    _check_value("value", args, min_val, max_val)
    return args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Accept list of tuples or dict
    if args is None:
        return {}, {}
    if isinstance(args, list):
        try:
            args = dict(args)
        except Exception as exc:
            raise ValueError("args list must contain key/value pairs") from exc
    if not isinstance(args, dict):
        raise TypeError("args must be a dict or list of key/value pairs")

    control_args = {}
    nested_args = {}
    for key, value in args.items():
        if isinstance(key, str) and key.startswith("ansible_"):
            nested_args[key] = value
        else:
            control_args[key] = value
    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    try:
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
        elif isinstance(extra_vars, list):
            for item in extra_vars:
                if isinstance(item, dict):
                    vars_dict.update(item)
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                    vars_dict[key] = value
                else:
                    raise ValueError(f"Unsupported item type in extra_vars: {item!r}")
        else:
            raise TypeError("extra_vars must be a dict, list, or None")
    except Exception as exc:
        raise ValueError(f"Failed to merge extra_vars: {exc}") from exc

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Basic validation
    if not playbook_path:
        raise ValueError("playbook_path must be provided")
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Build base command
    cmd = ["ansible-playbook"]

    # Verbosity handling
    if verbose is None:
        verbosity = "-v"
    else:
        if isinstance(verbose, int):
            verbosity = "-v" * max(1, verbose)
        else:
            verbosity = str(verbose)
    cmd.append(verbosity)

    # Add ansible_args
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
            else:
                cmd.append(f"--{key}={value}")

    # Add extra_vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        # Convert to JSON string for safety
        try:
            json_vars = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError(f"Failed to serialize extra_vars: {exc}") from exc
        cmd.extend(["--extra-vars", json_vars])

    # Finally add the playbook path
    cmd.append(playbook_path)

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook executable not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    # Raise if non-zero exit code
    if result.returncode != 0:
        err_msg = result.stderr.strip() or "Unknown error"
        raise RuntimeError(f"ansible-playbook failed with exit code {result.returncode}: {err_msg}")

    # Return stdout
    return result.stdout.strip()

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Helper to determine if a string represents an integer
    def _is_int(s):
        try:
            int(s)
            return True
        except (ValueError, TypeError):
            return False

    # Helper to determine if a string represents a float
    def _is_float(s):
        try:
            float(s)
            return True
        except (ValueError, TypeError):
            return False

    # Helper to determine if a string represents a boolean
    def _is_bool(s):
        return isinstance(s, str) and s.lower() in {"true", "false", "yes", "no", "1", "0"}

    # Helper to convert a string to a boolean
    def _to_bool(s):
        return s.lower() in {"true", "yes", "1"}

    # Iterate over a copy of the items to avoid runtime errors when modifying the dict
    for key, val in list(values_dict.items()):
        # Skip non-string values
        if not isinstance(val, str):
            continue

        # Attempt integer conversion
        if _is_int(val):
            try:
                values_dict[key] = int(val)
                continue
            except Exception:
                pass

        # Attempt float conversion
        if _is_float(val):
            try:
                values_dict[key] = float(val)
                continue
            except Exception:
                pass

        # Attempt boolean conversion
        if _is_bool(val):
            try:
                values_dict[key] = _to_bool(val)
                continue
            except Exception:
                pass

        # Attempt list conversion for comma‑separated values
        if "," in val:
            try:
                values_dict[key] = [item.strip() for item in val.split(",")]
                continue
            except Exception:
                pass

        # If none of the above, leave the value as the original string
        # (no action needed)
        continue

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    os = __import__('os')
    json = __import__('json')

    # Validate plugin_dir
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Plugin directory '{plugin_dir}' does not exist or is not a directory.")

    # Determine spec file path (supporting common names)
    spec_filenames = ['plugin.json', 'plugin.yaml', 'plugin.yml']
    spec_path = None
    for name in spec_filenames:
        candidate = os.path.join(plugin_dir, name)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'. Expected one of: {', '.join(spec_filenames)}")

    # Load spec (JSON only for simplicity; YAML support can be added if needed)
    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            if spec_path.endswith('.json'):
                spec_data = json.load(f)
            else:
                # Attempt to parse YAML if available
                try:
                    yaml = __import__('yaml')
                    spec_data = yaml.safe_load(f)
                except Exception:
                    raise ValueError(f"Unsupported spec format for file '{spec_path}'. Only JSON or YAML are supported.")
    except Exception as exc:
        raise ValueError(f"Failed to read or parse plugin spec file '{spec_path}': {exc}") from exc

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    if not isinstance(spec_data, dict):
        raise ValueError(f"Plugin spec file '{spec_path}' does not contain a JSON object at the top level.")

    return _flatten(spec_data)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not root:
        return path
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    if norm_path == norm_root:
        return ''
    try:
        common = os.path.commonpath([norm_path, norm_root])
    except ValueError:
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
    if common != norm_root:
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
    return os.path.relpath(norm_path, norm_root)
